            new List<StatusUpdate>
            {
                new(new DateTimeOffset(2026, 7, 3, 8, 0, 0, TimeSpan.Zero), "Package picked up from sender"),
                new(new DateTimeOffset(2026, 7, 4, 14, 30, 0, TimeSpan.Zero), "Arrived at sorting facility - Chicago, IL"),
                new(new DateTimeOffset(2026, 7, 5, 9, 15, 0, TimeSpan.Zero), "In transit to destination"),
            }),
        ["TRK-002"] = new ShipmentDetails(
            "TRK-002",
            "Delivered",
            "Austin, TX",
            new DateTimeOffset(2026, 7, 5, 12, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new(new DateTimeOffset(2026, 7, 1, 10, 0, 0, TimeSpan.Zero), "Package picked up from sender"),
                new(new DateTimeOffset(2026, 7, 2, 16, 0, 0, TimeSpan.Zero), "Arrived at regional hub - Dallas, TX"),
                new(new DateTimeOffset(2026, 7, 4, 8, 45, 0, TimeSpan.Zero), "Out for delivery"),
                new(new DateTimeOffset(2026, 7, 4, 14, 20, 0, TimeSpan.Zero), "Delivered - Left at front door"),
            }),
        ["TRK-003"] = new ShipmentDetails(
            "TRK-003",
            "Processing",
            "Seattle, WA",
            new DateTimeOffset(2026, 7, 14, 18, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new(new DateTimeOffset(2026, 7, 6, 11, 0, 0, TimeSpan.Zero), "Order received - awaiting pickup"),
            }),
    };

    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

